import 'dart:io';
import 'package:flutter/material.dart';
import 'external_quiz_page.dart';
import 'models.dart';

/// Preserves the alternatives and explanations generated by the external AI.
class ExternalQuizRunnerPage extends StatefulWidget {
  const ExternalQuizRunnerPage({super.key, required this.guide});
  final StudyGuide guide;
  @override State<ExternalQuizRunnerPage> createState() => _ExternalQuizRunnerPageState();
}

class _ExternalQuizRunnerPageState extends State<ExternalQuizRunnerPage> {
  List<Map<String, dynamic>>? questions;
  String error = '';
  int index = 0;
  int score = 0;
  bool checked = false;
  bool lastAnswerCorrect = false;
  String choice = '';
  final response = TextEditingController();

  @override void initState() { super.initState(); _load(); }
  @override void dispose() { response.dispose(); super.dispose(); }

  Future<void> _load() async {
    try {
      if (widget.guide.filePath == null) {
        throw const FormatException('No se encuentra el archivo del examen.');
      }
      final raw = await File(widget.guide.filePath!).readAsString();
      final pack = ExternalQuizFormat.parse(raw);
      final items = (pack['questions'] as List)
          .map((e) => Map<String, dynamic>.from(e as Map)).toList();
      if (mounted) setState(() => questions = items);
    } catch (e) {
      if (mounted) setState(() => error = e.toString());
    }
  }

  bool _matches(Map<String, dynamic> item) {
    final answer = (item['answer'] as String).trim().toLowerCase();
    final user = (item['type'] == 'multiple_choice' ? choice : response.text)
        .trim().toLowerCase();
    if (user == answer) return true;
    if (item['type'] != 'short_answer') return false;
    final variants = item['accepted_answers'];
    return variants is List && variants.any((v) => v.toString().trim().toLowerCase() == user);
  }

  void _next() {
    setState(() {
      index++;
      checked = false;
      choice = '';
      response.clear();
    });
  }

  @override Widget build(BuildContext context) {
    if (error.isNotEmpty) {
      return Scaffold(appBar: AppBar(title: const Text('Examen')),
          body: Center(child: Text(error)));
    }
    final bank = questions;
    if (bank == null) return const Scaffold(
        body: Center(child: CircularProgressIndicator()));
    if (index >= bank.length) {
      return Scaffold(appBar: AppBar(title: const Text('Resultados')),
        body: Center(child: Column(mainAxisSize: MainAxisSize.min, children: [
          Text('Resultado: ' + score.toString() + ' / ' + bank.length.toString(),
            style: const TextStyle(fontSize: 26, fontWeight: FontWeight.bold)),
          const SizedBox(height: 12),
          FilledButton(onPressed: () => Navigator.pop(context),
            child: const Text('Volver a Biblioteca')),
        ])));
    }

    final question = bank[index];
    final isChoice = question['type'] == 'multiple_choice';
    return Scaffold(
      appBar: AppBar(title: Text('Pregunta ' + (index + 1).toString() + ' de ' + bank.length.toString())),
      body: ListView(padding: const EdgeInsets.all(18), children: [
        Text(question['question'].toString(),
          style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 21)),
        const SizedBox(height: 18),
        if (isChoice)
          for (final option in (question['options'] as List))
            RadioListTile<String>(
              title: Text(option.toString()),
              value: option.toString(),
              groupValue: choice,
              onChanged: checked ? null : (v) => setState(() => choice = v ?? '')),
        if (!isChoice)
          TextField(
            controller: response,
            readOnly: checked,
            decoration: const InputDecoration(labelText: 'Tu respuesta'),
          ),
        const SizedBox(height: 18),
        if (checked) ...[
          Text(lastAnswerCorrect ? 'Respuesta correcta' :
            'Respuesta incorrecta. La correcta es: ' + question['answer'].toString(),
            style: const TextStyle(fontWeight: FontWeight.bold)),
          const SizedBox(height: 6),
          if ((question['explanation'] ?? '').toString().trim().isNotEmpty)
            Text(question['explanation'].toString()),
          const SizedBox(height: 12),
        ],
        FilledButton(
          onPressed: () {
            if (checked) {
              _next();
              return;
            }
            if ((isChoice ? choice : response.text).trim().isEmpty) return;
            final right = _matches(question);
            setState(() {
              checked = true;
              lastAnswerCorrect = right;
              if (right) score++;
            });
          },
          child: Text(checked ? 'Siguiente' : 'Comprobar'),
        ),
      ]),
    );
  }
}
